import zipfile
import xml.etree.ElementTree as ET

NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
def q(t): return '{%s}%s' % (NS, t)

z = zipfile.ZipFile('budget.xlsx')
root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
rows = {}
for row in root.find(q('sheetData')).findall(q('row')):
    for c in row.findall(q('c')):
        v = c.find(q('v'))
        rows[c.get('r')] = v.text if v is not None else None

items = []
for r in range(11, 23):
    cat, desc, amt = rows.get('A%d' % r), rows.get('B%d' % r), rows.get('C%d' % r)
    items.append((cat, desc, float(amt)))

cats = {}
total = 0.0
for cat, desc, amt in items:
    cats[cat] = cats.get(cat, 0.0) + amt
    total += amt

print("Per-item expenses:")
for cat, desc, amt in items:
    print("  %-15s %-20s %.2f" % (cat, desc, amt))
print("\nPer-category totals:")
for cat, s in cats.items():
    print("  %-15s %.2f" % (cat, s))
print("\nTOTAL EXPENSES (rows 11-22): %.2f" % total)
print("Formula at C23: =SUM(C11:C22)")

