import zipfile
import re
import xml.etree.ElementTree as ET

NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
def q(t): return '{%s}%s' % (NS, t)

z = zipfile.ZipFile('budget.xlsx')

shared = []
if 'xl/sharedStrings.xml' in z.namelist():
    root = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in root.findall(q('si')):
        shared.append(''.join(t.text or '' for t in si.iter(q('t'))))

def cell_value(c, shared):
    t = c.get('t')
    v = c.find(q('v'))
    isel = c.find(q('is'))
    if t == 's' and v is not None:
        return shared[int(v.text)]
    if t == 'inlineStr' and isel is not None:
        return ''.join(x.text or '' for x in isel.iter(q('t')))
    if v is not None:
        raw = v.text
        if t == 'str' or t is None:
            try:
                return float(raw) if re.match(r'^-?\d+\.?\d*$', raw) else raw
            except (TypeError, ValueError):
                return raw
        return raw
    return None

root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
rows = {}
for row in root.find(q('sheetData')).findall(q('row')):
    for c in row.findall(q('c')):
        rows[c.get('r')] = (c.get('t'), cell_value(c, shared))

print("Rows 1..30 of sheet1 (ref: type, value):")
for r in range(1, 31):
    for col in 'ABCDE':
        ref = '%s%d' % (col, r)
        if ref in rows:
            print('  %-4s %s: %r' % (ref, rows[ref][0], rows[ref][1]))

# Per-category totals from rows 11-22 using column A as category, C as amount
cats = {}
total = 0.0
print("\nExpense line items (rows 11-22):")
for r in range(11, 23):
    cat_ref = 'A%d' % r
    desc_ref = 'B%d' % r
    amt_ref = 'C%d' % r
    cat = rows.get(cat_ref, (None, None))[1]
    desc = rows.get(desc_ref, (None, None))[1]
    amt = rows.get(amt_ref, (None, None))[1]
    try:
        amt = float(amt)
    except (TypeError, ValueError):
        amt = 0.0
    cats[cat] = cats.get(cat, 0.0) + amt
    total += amt
    print('  %-4s cat=%r desc=%r amt=%.2f' % (amt_ref, cat, desc, amt))

print("\nPer-category totals:")
for cat, s in sorted(cats.items(), key=lambda kv: (kv[0] is None, kv[0] or '')):
    print('  %-20s %.2f' % (cat, s))
print("GRAND TOTAL (sum of all category amounts): %.2f" % total)

